// Full-sync parser: output every non-empty sheet row. Supabase handles exact duplicate full_text rows.
const STATES = {
  AL:'Alabama', AK:'Alaska', AZ:'Arizona', AR:'Arkansas', CA:'California', CO:'Colorado', CT:'Connecticut', DE:'Delaware', FL:'Florida', GA:'Georgia',
  HI:'Hawaii', ID:'Idaho', IL:'Illinois', IN:'Indiana', IA:'Iowa', KS:'Kansas', KY:'Kentucky', LA:'Louisiana', ME:'Maine', MD:'Maryland',
  MA:'Massachusetts', MI:'Michigan', MN:'Minnesota', MS:'Mississippi', MO:'Missouri', MT:'Montana', NE:'Nebraska', NV:'Nevada', NH:'New Hampshire', NJ:'New Jersey',
  NM:'New Mexico', NY:'New York', NC:'North Carolina', ND:'North Dakota', OH:'Ohio', OK:'Oklahoma', OR:'Oregon', PA:'Pennsylvania', RI:'Rhode Island', SC:'South Carolina',
  SD:'South Dakota', TN:'Tennessee', TX:'Texas', UT:'Utah', VT:'Vermont', VA:'Virginia', WA:'Washington', WV:'West Virginia', WI:'Wisconsin', WY:'Wyoming', DC:'District of Columbia'
};
const STATES_REV = Object.fromEntries(Object.entries(STATES).map(([abbr, name]) => [name.toLowerCase(), abbr]));
const STREET_HINT = /^(?:\d+|US-|NJ-|NY-|CA-|I-\d|Route\b)|\b(?:Street|St|Avenue|Ave|Road|Rd|Boulevard|Blvd|Highway|Hwy|Drive|Dr|Lane|Ln|Court|Ct|Parkway|Pkwy|Plaza|Pl|Way|Circle|Cir|Place|Square|Sq|Suite|Ste|Floor|Fl|Building|Bldg|Turnpike|Tpke|Terrace|Ter|Expressway|Expy|Freeway|Fwy|Trail|Trl|Center|Ctr)\b/i;

function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

function getRowText(row) {
  if (typeof row === 'string') return clean(row);
  if (!row || typeof row !== 'object') return '';

  const values = [];
  const headerKeys = [];
  for (const [key, value] of Object.entries(row)) {
    if (key === 'row_number' || key === '__index') continue;

    const v = clean(value);
    if (v) values.push(v);

    // Fallback only. In no-header sheets, n8n can put the first row as a key.
    const k = clean(key);
    if (k && k !== 'A' && k !== 'Column 1' && k.length > 3) headerKeys.push(k);
  }

  const candidates = values.length ? values : headerKeys;
  candidates.sort((a, b) => b.length - a.length);
  return candidates[0] || '';
}

function parseState(text) {
  let state = null;
  for (const match of text.matchAll(/\b([A-Z]{2})\b/g)) {
    if (STATES[match[1]]) state = match[1];
  }
  if (state) return state;

  const lower = text.toLowerCase();
  for (const [name, abbr] of Object.entries(STATES_REV)) {
    if (lower.includes(name)) return abbr;
  }
  return null;
}

function fallbackCompany(text) {
  const beforeDash = clean(text.split(' - ')[0]);
  if (beforeDash && !STREET_HINT.test(beforeDash)) return beforeDash;

  const beforeComma = clean(text.split(',')[0]);
  if (beforeComma && !STREET_HINT.test(beforeComma)) return beforeComma;

  return clean(beforeDash || beforeComma || text).slice(0, 250);
}

function parseFullText(text) {
  const out = { company: null, street: null, city: null, state: parseState(text), zip: null };

  // KEY FIX: extract zip from end of full_text (" - 60506" pattern) first.
  // Street numbers at the start of addresses are also 5 digits, taking the first match caused wrong values.
  const endZip = text.match(/ - (\d{5})$/);
  if (endZip) {
    out.zip = endZip[1];
  } else {
    // Fallback: last 5-digit number in the string
    const allZips = [...text.matchAll(/\b(\d{5})(?:-\d{4})?\b/g)];
    if (allZips.length > 0) out.zip = allZips[allZips.length - 1][1];
  }

  let addrPart = text;
  const dashIdx = text.indexOf(' - ');
  if (dashIdx > 0) {
    out.company = clean(text.slice(0, dashIdx));
    addrPart = clean(text.slice(dashIdx + 3));
  } else {
    const commaIdx = text.indexOf(',');
    if (commaIdx > 0) {
      const left = clean(text.slice(0, commaIdx));
      if (left && !STREET_HINT.test(left)) {
        out.company = left;
        addrPart = clean(text.slice(commaIdx + 1));
      }
    }
  }

  const parts = addrPart.split(',').map(clean).filter(Boolean);
  const streetIndex = parts.findIndex(part => STREET_HINT.test(part));
  if (streetIndex >= 0) {
    out.street = parts[streetIndex];
    if (parts[streetIndex + 1]) out.city = parts[streetIndex + 1];
  } else if (parts.length >= 2) {
    out.city = parts[0];
  }

  out.company = out.company || fallbackCompany(text);
  return out;
}

const output = [];
let emptyRows = 0;
for (const item of $input.all()) {
  const text = getRowText(item.json);
  if (!text || text.length < 2) {
    emptyRows++;
    continue;
  }

  const parsed = parseFullText(text);
  output.push({
    json: {
      full_text: text,
      company: parsed.company,
      street: parsed.street,
      city: parsed.city,
      state: parsed.state,
      zip: parsed.zip
    }
  });
}

console.log('Parse Sheet Rows output:', output.length, 'empty rows skipped:', emptyRows);
return output;

const payload = $input.all()
  .map(item => ({
    full_text: item.json.full_text,
    company: item.json.company,
    street: item.json.street || null,
    city: item.json.city || null,
    state: item.json.state || null,
    zip: item.json.zip || null
  }))
  .filter(row => row.full_text && row.company);

if (payload.length === 0) return [];
return [{ json: { payload, batch_size: payload.length } }];

return [{
  json: {
    summary: 'No-parse-dedupe sync completed. Check Supabase count; duplicate full_text rows are still ignored by Supabase.',
    completed_at: new Date().toISOString()
  }
}];
